window.CourseSearchIndex=[{"title": "Kepler ellipse", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/kepler-ellipse/", "text": "An ellipse sweeps equal areas in equal times"}, {"title": "GEO & rotating Earth", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/geo-frames/", "text": "A stationary point in the sky is moving in space"}, {"title": "Elevation & horizon", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/look-triangle/", "text": "Elevation is an angle at the station, not Earth’s center"}, {"title": "Azimuth quadrants", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/azimuth-components/", "text": "East and north components determine the bearing"}, {"title": "Solar push", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/solar-pressure-components/", "text": "Project one sunlight push onto rotating orbital axes"}, {"title": "Integration drift", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/numerical-orbits/", "text": "The same physics can produce different numerical drift"}, {"title": "Two-burn transfer", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/hohmann-transfer/", "text": "One burn raises apogee; the next circularizes"}, {"title": "Eclipse & battery", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/eclipse-battery/", "text": "One eclipse is an energy bill; every orbit must repay it"}, {"title": "Solar array", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/solar-array/", "text": "Sun-facing area and cell performance set useful power"}, {"title": "Rocket equation", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/rocket-mass/", "text": "A later burn’s fuel must ride through every earlier burn"}, {"title": "Electric thrust", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/electric-propulsion/", "text": "High exhaust speed saves propellant but costs thrust at fixed power"}, {"title": "Heat & radiator", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/thermal-balance/", "text": "RF power, waste heat and radiator temperature are connected"}, {"title": "dB & distance", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/db-distance/", "text": "Logarithms turn power ratios into distances you can compare"}, {"title": "Link budget", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/link-budget/", "text": "Follow carrier power to the receiver, then compare it with noise"}, {"title": "Noise cascade", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/receiver-noise/", "text": "A lossy first stage makes later low-noise gain less useful"}, {"title": "Doppler", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/doppler-shift/", "text": "Only the line-of-sight velocity changes range instantaneously"}, {"title": "Rain & elevation", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/rain-path/", "text": "A low look angle takes a longer path through the rain"}, {"title": "Bandwidth & noise", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/bandwidth-noise/", "text": "More bandwidth admits more noise but may carry more information"}, {"title": "Radiation & voting", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/radiation-redundancy/", "text": "Three copies mask one bad bit; shared failures can defeat the vote"}, {"title": "Divergence & curl", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/divergence-curl/", "text": "Outward flow and local circulation measure different things"}, {"title": "Standing waves", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/standing-wave/", "text": "Counter-propagating waves can leave fixed nodes"}, {"title": "E, H & energy", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/plane-wave/", "text": "A plane wave carries perpendicular fields together"}, {"title": "Polarization", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/polarization/", "text": "Watch the electric-field tip trace its polarization"}, {"title": "Interference & phasors", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/phasor-interference/", "text": "Add fields before squaring to find power"}, {"title": "Double curl pinwheels", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/double-curl/", "text": "Pinwheels measure the swirl of the axle field"}, {"title": "Displacement current", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/displacement-current/", "text": "A charging capacitor keeps magnetic circulation continuous"}, {"title": "Helmholtz curvature", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/helmholtz-curvature/", "text": "The wave equation ties spatial curvature to the field"}, {"title": "Dipole patterns", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/dipole-pattern/", "text": "A doughnut-shaped beam has an axial null"}, {"title": "Aperture addition", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/aperture-phasors/", "text": "A pattern comes from adding fields with phase"}, {"title": "Circular aperture", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/circular-aperture/", "text": "A circular opening produces a Bessel beam"}, {"title": "Dish and pointing", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/dish-gain/", "text": "A larger dish collects more power and needs better pointing"}, {"title": "Usable band", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/reflector-screens/", "text": "Electrical size, surface precision, and range set different screens"}, {"title": "Arrays", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-multiplication/", "text": "The array factor multiplies the element pattern"}, {"title": "Gain and matching", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/gain-references/", "text": "Accepted, radiated, and incident power use different references"}, {"title": "Path + feed phase", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-path-phase/", "text": "Why broadside adds while another direction cancels"}, {"title": "Planar steering", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/planar-array/", "text": "A plane of elements controls two directional coordinates"}, {"title": "Beam to footprint", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-footprint/", "text": "An angular beam becomes a patch of ground through geometry"}, {"title": "GPS orbit geometry", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-orbits/", "text": "Inclined MEO planes spread satellites across the sky"}, {"title": "Doppler pass", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/doppler-pass/", "text": "A nearer pass changes its range rate more sharply"}, {"title": "Range & clock", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/pseudorange-clock/", "text": "One clock offset adds the same distance error to every pseudorange"}, {"title": "Geometry & precision", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-geometry/", "text": "Similar range errors can produce very different position uncertainty"}, {"title": "Code correlation", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/pn-correlation/", "text": "A delayed code is found by testing many alignments"}, {"title": "Sampling & aliasing", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/sampling-alias/", "text": "Different continuous waves can give exactly the same samples"}, {"title": "Quantization & PCM", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/quantization-pcm/", "text": "Sampling fixes when; quantization fixes which amplitude level"}, {"title": "Compression vs coding", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/source-compression/", "text": "Compression removes redundancy; error correction deliberately adds it"}, {"title": "Pulses & ISI", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/nyquist-pulse/", "text": "A pulse can overlap its neighbors while giving zero interference at the right sampling instants"}, {"title": "I/Q & decisions", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/iq-constellation/", "text": "A modulation symbol chooses one point in the I/Q plane"}, {"title": "Bits, baud & bandwidth", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/rate-bandwidth/", "text": "Keep information bits, coded bits and modulation symbols separate"}, {"title": "Adaptive MODCOD", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/adaptive-modcod/", "text": "Use a robust mode in a fade and a faster mode when margin returns"}, {"title": "Amplifier & backoff", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/amplifier-backoff/", "text": "Constellation geometry changes what a nonlinear amplifier distorts"}, {"title": "Pattern to absolute gain", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-normalization/", "text": "A relative pattern becomes directivity only after angular integration"}, {"title": "Solid angle and power", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/solid-angle/", "text": "Equal angular rectangles cover different areas on a sphere"}, {"title": "Spreading and capture", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/free-space-flux/", "text": "A receiver captures a small part of an expanding power flow"}, {"title": "Pulse width and spectrum", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/rectangular-pulse-spectrum/", "text": "A short rectangular pulse spreads across a wide range of frequencies"}, {"title": "Matched filter and timing", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/matched-filter/", "text": "A time-reversed pulse collects a known waveform into a decision sample"}, {"title": "Shift register and PN code", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/lfsr-code/", "text": "A short binary recurrence creates a long recognizable chip sequence"}, {"title": "Spreading and processing gain", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/processing-gain/", "text": "A known fast code lets the receiver collect a slow data bit coherently"}, {"title": "Range-error budget", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-error-budget/", "text": "Independent range uncertainties add through their variances"}, {"title": "Earth-fixed coordinates", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/navigation-frames/", "text": "Earth-fixed coordinates turn latitude and longitude into Cartesian positions"}, {"title": "CDMA near–far effect", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/near-far/", "text": "A strong unwanted code can overwhelm a weaker desired correlation"}, {"title": "Multipath and OFDM", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/ofdm-multipath/", "text": "A delayed echo makes channel gain vary across frequency"}, {"title": "Analog and digital combining", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/beamforming-frontends/", "text": "The location of beamforming changes which hardware sees interference"}, {"title": "Dual-frequency ranging", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/dual-frequency/", "text": "Two frequencies separate the leading ionospheric delay from common range"}, {"title": "Code-delay and Doppler search", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-acquisition/", "text": "A receiver searches code alignment and carrier frequency together"}, {"title": "The modem signal chain", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/modem-chain/", "text": "Rates and waveform choices belong to specific stages of the modem"}, {"title": "Three-dimensional DOP", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-dop-3d/", "text": "Six sky directions constrain east, north, up and receiver clock together"}, {"title": "Authenticated encryption", "course": "gt/ece6612", "code": "ECE 6612", "group": "Foundations", "route": "/courses/gt/ece6612/topics/authenticated-encryption/", "text": "Authenticated encryption with associated data takes a secret key K, nonce N, plaintext P, and associated data A. It protects P while binding the visible context A to that protected message. The diagram shows the authentication tag separately; an algorithm may encode it inside its ciphertext output. Authenticated decryption returns plaintext or failure. The receiver releases plaintext only after successful verification. For a nonce-based mode such as AES-GCM, encryption nonces must be unique for a given key; secrecy of the nonce is unnecessary. Message authentication and replay policy have separate jobs. A previously valid packet can still be a replay, so the surrounding protocol must enforce its sequence or freshness rules. A handshake can bind the symmetric key to an intended peer identity."}, {"title": "TLS identity and session keys", "course": "gt/ece6612", "code": "ECE 6612", "group": "Foundations", "route": "/courses/gt/ece6612/topics/tls-session-keys/", "text": "Ephemeral Diffie–Hellman lets two peers compute a common secret from private contributions and public key shares. In finite-field notation, A = gᵃ mod p and B = gᵇ mod p give Bᵃ = Aᵇ = gᵃᵇ mod p. Modern TLS can instead use an elliptic-curve group. An unauthenticated exchange can establish a secret with an impersonator. In the certificate-authenticated TLS 1.3 flow shown, the client validates the certificate for its intended server identity and verifies the server's CertificateVerify transcript signature. Certificate-path validation and application identity checking have complementary roles. HKDF derives separate traffic keys using the shared secret and protocol context. Finished authenticates the handshake under a derived key, confirming the computed key material and transcript. Certificate authentication, ephemeral key agreement, and encrypted application records therefore remain separate steps."}, {"title": "Equilibrium carrier populations", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/carrier-populations/", "text": "Conduction electrons and holes are mobile carriers with charges −q and +q. In an intrinsic semiconductor at thermal equilibrium, their concentrations are equal: n = p = nᵢ. The intrinsic concentration depends strongly on temperature. In the nondegenerate equilibrium model, np = nᵢ². Fully ionized donor doping with ND much larger than nᵢ gives approximately n = ND and p = nᵢ²/ND when acceptor compensation is negligible. Ionized donors supply positive fixed charge that balances the mobile electrons in a neutral bulk region. The Fermi level describes equilibrium occupancy. Moving it closer to the conduction-band edge increases electron population relative to holes. These simple concentration formulas require their stated temperature, ionization, and nondegeneracy assumptions; heavy doping or nonequilibrium needs a fuller model."}, {"title": "MOS gate electrostatics", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-gate-electrostatics/", "text": "A MOS structure places an insulating oxide between a gate and semiconductor. For a p-type body, increasing positive gate bias first repels holes and exposes negative ionized acceptors. Sufficient surface band bending attracts an electron inversion layer. The oxide capacitance per unit area is C′ox = εox/tox. With surface potential ψs measured relative to the bulk, the ideal voltage split is Vg − VFB = ψs + Vox. Gate sheet charge is Q′g = C′oxVox, in C/m², and balances the semiconductor sheet charge when additional oxide charges are absent. Oxide capacitance and measured MOS capacitance are different quantities. In depletion, semiconductor charge changes contribute an additional series capacitance. Inversion response also depends on measurement frequency and carrier supply. Specify regime and frequency before interpreting a C–V curve."}, {"title": "GeorgiaTenna project", "course": "gt/ece6390", "code": "ECE 6390", "group": "Interactive tools", "route": "/courses/gt/ece6390/project/", "text": "Aperture, feeds, phases, steering, normalization, link budget and geographic coverage"}, {"title": "Orbit and Sun", "course": "gt/ece6390", "code": "ECE 6390", "group": "Interactive tools", "route": "/courses/gt/ece6390/orbit/", "text": "Orbital forces, look angles and Sun geometry"}, {"title": "Solar acceleration components", "course": "gt/ece6390", "code": "ECE 6390", "group": "Interactive tools", "route": "/courses/gt/ece6390/solar/", "text": "Radial and tangential projections of solar pressure"}];
